// =============================================================================
// PROJET SABOTEUR V2 - jeu de donnees
// =============================================================================
// A jouer une fois, en administrateur.
// Avec la pile docker du cours (profil simple, compte amiral) :
//     mongosh -u amiral -p amiral --authenticationDatabase admin saboteur-v2-donnees.js
// Sur un serveur sans authentification :   mongosh saboteur-v2-donnees.js
// Cree la base "LOG_FLOTTE_MN" ; le script la vide d'abord, on peut le rejouer.
// Cree aussi le compte de l'enqueteur, en lecture seule sur cette base :
//     mongosh "mongodb://enqueteur:ENQ-0405@localhost:27017/LOG_FLOTTE_MN"   // push-check: allow (the enonce V2 public course login)
// Sur un serveur lance sans authentification (un mongod installe a la main, par exemple),
// le badge se connecte aussi, mais rien n'empeche d'ecrire : les journaux sont des preuves,
// n'y touchez pas.
// =============================================================================

const base = db.getSiblingDB("LOG_FLOTTE_MN");
base.dropDatabase();
if (base.getUser("enqueteur")) base.dropUser("enqueteur");
base.createUser({ user: "enqueteur", pwd: "ENQ-0405", roles: [{ role: "read", db: "LOG_FLOTTE_MN" }] });

